import React, { useEffect, useRef, useState } from "react";
import * as THREE from "three";

const PHOTO_B64 = "";

const skillsData = [
  { cat: "Languages", items: ["Java (OOP, Collections, Exception Handling)"] },
  { cat: "Backend", items: ["Spring Boot", "Spring", "JDBC", "Hibernate", "REST APIs", "JWT Auth"] },
  { cat: "Frontend", items: ["React.js", "HTML5", "CSS3", "JavaScript", "Bootstrap"] },
  { cat: "Databases", items: ["MySQL", "Firebase"] },
  { cat: "Tools", items: ["GitHub", "Postman", "Eclipse", "IntelliJ IDEA", "VS Code", "Cloudinary", "Maven"] },
];

const projectsData = [
  {
    title: "Career-Portal",
    desc: "Full-stack Job Portal with Candidate, Company, and Admin modules. JWT Auth + RBAC, RESTful APIs with Spring Boot & Hibernate, MySQL for user/job/application management, Cloudinary for resume & profile uploads.",
    tags: ["Spring Boot", "Hibernate", "React.js", "JWT", "MySQL", "Cloudinary"],
    link: "https://github.com/pushpakchopadekar/Career-Poratal",
  },
  {
    title: "JewelPro Billing System",
    desc: "Billing system for jewelry retailers with automated GST & invoice calculations, Admin/Staff role-based auth, and downloadable PDF invoices via jsPDF.",
    tags: ["React.js", "Firebase", "jsPDF"],
    link: "https://github.com/pushpakchopadekar/BB",
  },
];

const experienceData = [
  {
    role: "Software Developer Intern",
    org: "Pawar Technology Services, Pune",
    period: "Jan 2025 – Jul 2025",
    points: [
      "Developed responsive user interfaces using React.js and reusable components.",
      "Integrated frontend modules with Spring Boot REST APIs.",
      "Worked with MySQL and Firebase databases for data storage and retrieval.",
      "Participated in debugging and resolving frontend, backend, and database issues.",
    ],
  },
];

// Set this to your backend URL once deployed (e.g. "https://your-app.onrender.com")
const API_BASE = "https://myportfolio-production-c844.up.railway.app";
export default function Portfolio() {
  const [theme, setTheme] = useState("dark");
  const mountRef = useRef(null);
  const [loaded, setLoaded] = useState(false);
  const [activeSection, setActiveSection] = useState("home");

  const [skills, setSkills] = useState(skillsData);
  const [projects, setProjects] = useState(projectsData);
  const [experience, setExperience] = useState(experienceData);
  const [certifications, setCertifications] = useState([
    { title: "Java Full Stack Development Certification", issuer: "Verified credential", year: "" },
  ]);
  const [profile, setProfile] = useState({
    fullName: "Pushpak Chopadekar",
    heroEyebrow: "Available for opportunities",
    heroHeadline: "I build full-stack\nproducts that just work.",
    heroSub: "Pushpak Chopadekar — Java Full Stack Developer crafting scalable Spring Boot backends and smooth React interfaces, backed by production-style projects with auth, RBAC, and cloud integrations.",
    statExperience: "6mo",
    statCgpa: "8.47",
    email: "pushpakchopadekar@gmail.com",
    phone: "+91 7387416715",
    githubUrl: "https://github.com/pushpakchopadekar",
    linkedinUrl: "",
    photoAvailable: false,
  });

  const [form, setForm] = useState({ name: "", email: "", message: "" });
  const [formStatus, setFormStatus] = useState("");
  const [modalKey, setModalKey] = useState(null);
  const [mobileOpen, setMobileOpen] = useState(false);

  const modalContent = {
    about: { icon: "👋", title: "About Me", teaser: "Computer Engineering grad who turns backend logic into products people actually use — Spring Boot APIs on one side, React interfaces on the other.", cta: "Read full story" },
    skills: { icon: "🛠", title: "Tech Stack", teaser: "Java, Spring Boot, Hibernate & MySQL on the backend — React, JS & Bootstrap on the front. JWT + RBAC baked into real projects, not just tutorials.", cta: "See all skills" },
    experience: { icon: "💼", title: "Experience", teaser: "6 months building production UI + APIs at Pawar Technology Services — React front, Spring Boot back, MySQL + Firebase underneath.", cta: "View timeline" },
    projects: { icon: "🚀", title: "Projects", teaser: "Career-Portal — a full job-portal platform with RBAC. JewelPro — a GST-ready billing system. Both shipped end-to-end, solo.", cta: "Explore projects" },
    contact: { icon: "📬", title: "Let's Talk", teaser: "Open to Software Developer / Java Full Stack roles. Drop a message and I'll get back to you.", cta: "Open contact form" },
  };

  const openModal = (key) => { setModalKey(key); setMobileOpen(false); };
  const goToSection = (key) => {
    setModalKey(null);
    setTimeout(() => document.getElementById(key)?.scrollIntoView({ behavior: "smooth" }), 50);
  };

  // Scroll-reveal: fade/slide elements in as they enter the viewport
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("pf-visible");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.15, rootMargin: "0px 0px -60px 0px" }
    );
    const targets = document.querySelectorAll(".pf-observe");
    targets.forEach((t) => observer.observe(t));
    return () => observer.disconnect();
  }, [skills, projects, experience, certifications]);

  useEffect(() => {
    const t = setTimeout(() => setLoaded(true), 1400);
    return () => clearTimeout(t);
  }, []);

  // Pull live content from the backend if it's running; silently keep the
  // built-in defaults above if the backend isn't reachable yet.
  useEffect(() => {
    fetch(`${API_BASE}/api/public/profile`).then((r) => r.json()).then((data) => {
      if (data && data.fullName) {
        setProfile((prev) => ({ ...prev, ...data, photoAvailable: true }));
      }
    }).catch(() => {});

    fetch(`${API_BASE}/api/public/skills`).then((r) => r.json()).then((data) => {
      if (data && data.length) {
        const grouped = {};
        data.forEach((s) => {
          grouped[s.category] = grouped[s.category] || [];
          grouped[s.category].push(s.name);
        });
        setSkills(Object.entries(grouped).map(([cat, items]) => ({ cat, items })));
      }
    }).catch(() => {});

    fetch(`${API_BASE}/api/public/projects`).then((r) => r.json()).then((data) => {
      if (data && data.length) {
        setProjects(data.map((p) => ({
          title: p.title, desc: p.description,
          tags: (p.tags || "").split(",").map((t) => t.trim()).filter(Boolean),
          link: p.githubUrl,
        })));
      }
    }).catch(() => {});

    fetch(`${API_BASE}/api/public/experience`).then((r) => r.json()).then((data) => {
      if (data && data.length) {
        setExperience(data.map((e) => ({
          role: e.role, org: e.organization, period: e.period,
          points: (e.description || "").split("\n").filter(Boolean),
        })));
      }
    }).catch(() => {});

    fetch(`${API_BASE}/api/public/certifications`).then((r) => r.json()).then((data) => {
      if (data && data.length) setCertifications(data);
    }).catch(() => {});
  }, []);

  // Scroll-spy: highlight the current section's tab in the navbar
  useEffect(() => {
    const ids = ["home", "about", "skills", "experience", "projects", "certifications", "contact"];
    const onScroll = () => {
      let current = "home";
      for (const id of ids) {
        const el = document.getElementById(id);
        if (el && el.getBoundingClientRect().top <= 140) current = id;
      }
      setActiveSection(current);
    };
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const submitContact = async (e) => {
    e.preventDefault();
    setFormStatus("Sending...");
    try {
      const res = await fetch(`${API_BASE}/api/public/contact`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      if (!res.ok) throw new Error();
      setFormStatus("Message sent ✓");
      setForm({ name: "", email: "", message: "" });
    } catch {
      setFormStatus("Couldn't send — is the backend running?");
    }
  };

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;
    const width = mount.clientWidth;
    const height = mount.clientHeight;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 100);
    camera.position.set(0, 0, 7);

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mount.appendChild(renderer.domElement);

    const geo = new THREE.TorusGeometry(2.1, 0.14, 32, 100);
    const positions = geo.attributes.position;
    const colors = [];
    const cA = new THREE.Color(0x7f5af0);
    const cB = new THREE.Color(0x2cb1ff);
    const cC = new THREE.Color(0xff5da2);
    for (let i = 0; i < positions.count; i++) {
      const a = (positions.getX(i) + 2.3) / 4.6;
      const c = a < 0.5 ? cA.clone().lerp(cB, a * 2) : cB.clone().lerp(cC, (a - 0.5) * 2);
      colors.push(c.r, c.g, c.b);
    }
    geo.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
    const mat = new THREE.MeshStandardMaterial({
      vertexColors: true, roughness: 0.3, metalness: 0.2,
      emissive: 0x2a1a55, emissiveIntensity: 0.35,
    });
    const ring = new THREE.Mesh(geo, mat);
    scene.add(ring);

    const ring2 = ring.clone();
    ring2.scale.set(1.35, 1.35, 1.35);
    ring2.material = mat.clone();
    ring2.material.opacity = 0.25;
    ring2.material.transparent = true;
    ring2.rotation.x = Math.PI / 2.3;
    scene.add(ring2);

    const key = new THREE.PointLight(0x7f5af0, 6, 20);
    key.position.set(4, 3, 4); scene.add(key);
    const rim = new THREE.PointLight(0xff5da2, 5, 20);
    rim.position.set(-4, -2, 3); scene.add(rim);
    scene.add(new THREE.AmbientLight(0x404060, 1.2));

    const pGeo = new THREE.BufferGeometry();
    const pCount = 100;
    const pPos = new Float32Array(pCount * 3);
    for (let i = 0; i < pCount; i++) {
      pPos[i * 3] = (Math.random() - 0.5) * 12;
      pPos[i * 3 + 1] = (Math.random() - 0.5) * 12;
      pPos[i * 3 + 2] = (Math.random() - 0.5) * 6 - 2;
    }
    pGeo.setAttribute("position", new THREE.BufferAttribute(pPos, 3));
    const particles = new THREE.Points(pGeo, new THREE.PointsMaterial({ color: 0xffffff, size: 0.03, transparent: true, opacity: 0.45 }));
    scene.add(particles);

    let mouseX = 0, mouseY = 0;
    const onMouseMove = (e) => {
      mouseX = (e.clientX / window.innerWidth - 0.5) * 2;
      mouseY = (e.clientY / window.innerHeight - 0.5) * 2;
    };
    window.addEventListener("mousemove", onMouseMove);

    let raf, t = 0;
    const animate = () => {
      t += 0.006;
      ring.rotation.x = 1.1 + Math.sin(t * 0.5) * 0.15 + mouseY * 0.2;
      ring.rotation.y = t * 0.4 + mouseX * 0.3;
      ring2.rotation.y = -t * 0.25;
      ring2.rotation.x = 0.8 + Math.cos(t * 0.4) * 0.1;
      particles.rotation.y = t * 0.04;
      renderer.render(scene, camera);
      raf = requestAnimationFrame(animate);
    };
    animate();

    const onResize = () => {
      const w = mount.clientWidth, h = mount.clientHeight;
      camera.aspect = w / h; camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };
    window.addEventListener("resize", onResize);

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("resize", onResize);
      mount.removeChild(renderer.domElement);
      renderer.dispose();
    };
  }, []);

  const isDark = theme === "dark";

  return (
    <div className={`pf-root ${isDark ? "th-dark" : "th-light"}`}>
      <style>{`
        .pf-root {
          --violet: #7F5AF0; --blue: #2CB1FF; --pink: #FF5DA2;
          font-family: 'Poppins','Inter',system-ui,sans-serif;
          min-height: 100vh; position: relative; overflow-x: hidden;
          transition: background 0.4s ease, color 0.4s ease;
        }
        .th-dark {
          --bg: #0A0118; --bg2: #14082B; --card: rgba(255,255,255,0.05);
          --card-border: rgba(255,255,255,0.12); --text: #F3EFFF; --muted: #A79DC7;
          background: radial-gradient(1200px 600px at 80% 0%, rgba(127,90,240,0.22), transparent 60%),
                      radial-gradient(1000px 500px at 5% 95%, rgba(255,93,162,0.15), transparent 60%),
                      linear-gradient(180deg, var(--bg), var(--bg2));
          color: var(--text);
        }
        .th-light {
          --bg: #F6F4FD; --bg2: #FFFFFF; --card: #FFFFFF;
          --card-border: rgba(127,90,240,0.16); --text: #1A1030; --muted: #6E6289;
          --card-shadow: 0 10px 30px rgba(127,90,240,0.08);
          background: radial-gradient(1200px 600px at 80% 0%, rgba(127,90,240,0.12), transparent 60%),
                      radial-gradient(1000px 500px at 5% 95%, rgba(255,93,162,0.1), transparent 60%),
                      linear-gradient(180deg, var(--bg), var(--bg2));
          color: var(--text);
        }
        .th-light .pf-card, .th-light .pf-project-card, .th-light .pf-cert-row, .th-light .pf-modal-card {
          box-shadow: var(--card-shadow);
        }
        .th-light .pf-blob { opacity: 0.16; }
        .th-light .pf-chip { box-shadow: 0 10px 24px rgba(127,90,240,0.12); }
        .pf-blob { position: fixed; border-radius: 50%; filter: blur(90px); opacity: 0.3; pointer-events: none; z-index: 0; }
        .pf-blob-1 { width: 460px; height: 460px; background: var(--violet); top: -140px; right: -100px; }
        .pf-blob-2 { width: 400px; height: 400px; background: var(--pink); top: 900px; left: -100px; }
        .pf-blob-3 { width: 400px; height: 400px; background: var(--blue); top: 1800px; right: -60px; }

        .pf-loader {
          position: fixed; inset: 0; z-index: 100; display: flex; align-items: center; justify-content: center;
          flex-direction: column; gap: 18px; background: var(--bg);
          transition: opacity 0.6s ease, visibility 0.6s ease;
        }
        .pf-loader.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
        .pf-loader-ring {
          width: 64px; height: 64px; border-radius: 50%;
          border: 3px solid transparent;
          border-top-color: var(--violet); border-right-color: var(--blue); border-bottom-color: var(--pink);
          animation: pf-spin 1s linear infinite;
        }
        .pf-loader-text { font-size: 13px; letter-spacing: 3px; color: var(--muted); text-transform: uppercase; }
        @keyframes pf-spin { to { transform: rotate(360deg); } }

        .pf-nav {
          position: sticky; top: 0; z-index: 20;
          display: flex; justify-content: space-between; align-items: center;
          padding: 20px 48px; backdrop-filter: blur(14px);
          background: ${isDark ? "rgba(10,1,24,0.55)" : "rgba(247,245,252,0.7)"};
          border-bottom: 1px solid var(--card-border);
        }
        .pf-logo { font-weight: 700; font-size: 19px; display: flex; align-items: center; gap: 10px; }
        .pf-logo-dot { width: 12px; height: 12px; border-radius: 4px; background: linear-gradient(135deg, var(--violet), var(--blue), var(--pink)); box-shadow: 0 0 20px rgba(127,90,240,0.7); }
        .pf-navlinks { display: flex; gap: 30px; font-size: 14px; color: var(--muted); }
        .pf-navlinks a { color: var(--muted); text-decoration: none; cursor: pointer; transition: color 0.2s; position: relative; padding-bottom: 4px; }
        .pf-navlinks a:hover { color: var(--text); }
        .pf-navlinks a.active { color: var(--text); }
        .pf-navlinks a.active::after { content: ''; position: absolute; left: 0; right: 0; bottom: -6px; height: 2px; border-radius: 2px; background: linear-gradient(135deg, var(--violet), var(--pink)); }
        .pf-nav-right { display: flex; align-items: center; gap: 14px; }
        .pf-toggle {
          width: 38px; height: 38px; border-radius: 50%; border: 1px solid var(--card-border);
          background: var(--card); color: var(--text); cursor: pointer; font-size: 15px;
          display: flex; align-items: center; justify-content: center; transition: transform 0.3s ease;
        }
        .pf-toggle:hover { transform: rotate(20deg); }
        .pf-cta { padding: 11px 22px; border-radius: 999px; font-size: 13px; font-weight: 600; background: linear-gradient(135deg, var(--violet), var(--pink)); border: none; color: white; cursor: pointer; box-shadow: 0 8px 24px rgba(127,90,240,0.35); transition: transform 0.2s ease; }
        .pf-cta:hover { transform: translateY(-2px) scale(1.03); }

        section { position: relative; z-index: 2; padding: 90px 48px; max-width: 1280px; margin: 0 auto; }
        .pf-eyebrow { display: inline-flex; align-items: center; gap: 8px; font-size: 12px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--blue); background: rgba(44,177,255,0.1); border: 1px solid rgba(44,177,255,0.3); padding: 7px 14px; border-radius: 999px; margin-bottom: 20px; }
        .pf-h2 { font-size: clamp(28px,3.4vw,42px); font-weight: 700; margin: 0 0 12px; }
        .pf-gradient-text { background: linear-gradient(135deg, var(--violet), var(--blue), var(--pink)); -webkit-background-clip: text; background-clip: text; color: transparent; }
        .pf-section-sub { color: var(--muted); font-size: 15px; max-width: 560px; margin-bottom: 50px; line-height: 1.7; }

        .pf-hero { min-height: 88vh; display: grid; grid-template-columns: 1.05fr 1fr; align-items: center; padding-top: 40px; }
        .pf-headline { font-size: clamp(36px,5vw,62px); font-weight: 700; line-height: 1.08; margin: 0 0 20px; }
        .pf-sub { color: var(--muted); font-size: 17px; max-width: 480px; line-height: 1.7; margin-bottom: 30px; }
        .pf-cta-row { display: flex; gap: 16px; margin-bottom: 42px; flex-wrap: wrap; }
        .pf-btn-ghost { padding: 13px 26px; border-radius: 999px; font-size: 14px; font-weight: 500; background: var(--card); border: 1px solid var(--card-border); color: var(--text); cursor: pointer; backdrop-filter: blur(10px); transition: border-color 0.2s ease; }
        .pf-btn-ghost:hover { border-color: var(--blue); }
        .pf-stats { display: flex; gap: 40px; }
        .pf-stat-num { font-size: 28px; font-weight: 700; background: linear-gradient(135deg, var(--blue), var(--pink)); -webkit-background-clip: text; background-clip: text; color: transparent; }
        .pf-stat-label { font-size: 12px; color: var(--muted); margin-top: 2px; }

        .pf-hero-visual { position: relative; height: 480px; display: flex; align-items: center; justify-content: center; }
        .pf-canvas-wrap { position: absolute; inset: 0; }
        .pf-photo-card {
          position: relative; z-index: 3; width: 260px; height: 260px; border-radius: 50%;
          padding: 5px; background: linear-gradient(135deg, var(--violet), var(--blue), var(--pink));
          box-shadow: 0 20px 60px rgba(127,90,240,0.4);
          animation: pf-float 5s ease-in-out infinite;
        }
        .pf-photo-card img { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; display: block; border: 4px solid ${isDark ? "#0A0118" : "#F7F5FC"}; }
        @keyframes pf-float { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-14px); } }

        .pf-chip {
          position: absolute; z-index: 4; background: var(--card); border: 1px solid var(--card-border);
          backdrop-filter: blur(14px); border-radius: 12px; padding: 9px 14px; font-size: 12px;
          color: var(--text); display: flex; align-items: center; gap: 8px; box-shadow: 0 8px 20px rgba(0,0,0,0.2);
        }
        .pf-chip-dot { width: 7px; height: 7px; border-radius: 50%; background: #4ADE80; box-shadow: 0 0 8px #4ADE80; }
        .pf-chip-1 { top: 10px; left: -10px; animation: pf-float 4s ease-in-out infinite 0.3s; }
        .pf-chip-2 { bottom: 30px; right: -20px; animation: pf-float 4.5s ease-in-out infinite 0.6s; }

        .pf-reveal { opacity: 0; transform: translateY(24px); animation: pf-in 0.7s ease forwards; }
        .pf-observe { opacity: 0; transform: translateY(36px); transition: opacity 0.7s cubic-bezier(.2,.7,.2,1), transform 0.7s cubic-bezier(.2,.7,.2,1); }
        .pf-observe.pf-visible { opacity: 1; transform: translateY(0); }
        .pf-grid-cards .pf-observe:nth-child(1) { transition-delay: 0s; }
        .pf-grid-cards .pf-observe:nth-child(2) { transition-delay: 0.1s; }
        .pf-grid-cards .pf-observe:nth-child(3) { transition-delay: 0.2s; }
        .pf-grid-cards .pf-observe:nth-child(4) { transition-delay: 0.3s; }
        .pf-grid-cards .pf-observe:nth-child(5) { transition-delay: 0.4s; }
        .pf-timeline .pf-observe:nth-child(2) { transition-delay: 0.15s; }
        .pf-timeline .pf-observe:nth-child(3) { transition-delay: 0.3s; }

        .pf-modal-overlay { position: fixed; inset: 0; z-index: 60; background: rgba(5,2,15,0.7); backdrop-filter: blur(6px); display: flex; align-items: center; justify-content: center; padding: 20px; animation: pf-fade-in 0.25s ease; }
        @keyframes pf-fade-in { from { opacity: 0; } to { opacity: 1; } }
        .pf-modal-card { background: var(--bg2); border: 1px solid var(--card-border); border-radius: 22px; padding: 36px; max-width: 420px; width: 100%; position: relative; box-shadow: 0 30px 80px rgba(0,0,0,0.5); animation: pf-modal-in 0.35s cubic-bezier(.2,.8,.2,1); }
        @keyframes pf-modal-in { from { opacity: 0; transform: scale(0.9) translateY(20px); } to { opacity: 1; transform: scale(1) translateY(0); } }
        .pf-modal-icon { width: 56px; height: 56px; border-radius: 16px; background: linear-gradient(135deg, var(--violet), var(--blue), var(--pink)); display: flex; align-items: center; justify-content: center; font-size: 26px; margin-bottom: 18px; }
        .pf-modal-close { position: absolute; top: 18px; right: 18px; width: 32px; height: 32px; border-radius: 50%; border: 1px solid var(--card-border); background: var(--card); color: var(--text); cursor: pointer; font-size: 15px; }
        .pf-modal-card h3 { font-size: 22px; margin: 0 0 12px; }
        .pf-modal-card p { color: var(--muted); font-size: 14.5px; line-height: 1.7; margin-bottom: 26px; }

        .pf-hamburger { display: none; flex-direction: column; gap: 5px; width: 34px; height: 34px; align-items: center; justify-content: center; border: 1px solid var(--card-border); border-radius: 10px; background: var(--card); cursor: pointer; }
        .pf-hamburger span { width: 16px; height: 2px; background: var(--text); border-radius: 2px; transition: transform 0.3s ease, opacity 0.3s ease; }
        .pf-mobile-drawer { position: fixed; top: 0; right: 0; bottom: 0; width: 78vw; max-width: 300px; z-index: 55; background: var(--bg2); border-left: 1px solid var(--card-border); padding: 90px 30px 30px; transform: translateX(100%); transition: transform 0.35s cubic-bezier(.2,.8,.2,1); display: flex; flex-direction: column; gap: 6px; }
        .pf-mobile-drawer.open { transform: translateX(0); }
        .pf-mobile-drawer a { color: var(--text); text-decoration: none; font-size: 17px; padding: 14px 10px; border-bottom: 1px solid var(--card-border); opacity: 0; transform: translateX(20px); transition: opacity 0.4s ease, transform 0.4s ease; }
        .pf-mobile-drawer.open a { opacity: 1; transform: translateX(0); }
        .pf-mobile-drawer.open a:nth-child(1) { transition-delay: 0.08s; }
        .pf-mobile-drawer.open a:nth-child(2) { transition-delay: 0.14s; }
        .pf-mobile-drawer.open a:nth-child(3) { transition-delay: 0.2s; }
        .pf-mobile-drawer.open a:nth-child(4) { transition-delay: 0.26s; }
        .pf-mobile-drawer.open a:nth-child(5) { transition-delay: 0.32s; }
        .pf-mobile-backdrop { position: fixed; inset: 0; z-index: 50; background: rgba(0,0,0,0.5); backdrop-filter: blur(3px); }

        .pf-logo-mark { width: 34px; height: 34px; flex-shrink: 0; }
        @keyframes pf-in { to { opacity: 1; transform: translateY(0); } }

        .pf-grid-cards { display: grid; grid-template-columns: repeat(auto-fit,minmax(240px,1fr)); gap: 20px; }
        .pf-card {
          background: var(--card); border: 1px solid var(--card-border); border-radius: 18px;
          padding: 26px; backdrop-filter: blur(12px); transition: transform 0.25s ease, border-color 0.25s ease;
        }
        .pf-card:hover { transform: translateY(-6px); border-color: var(--violet); }
        .pf-card h3 { margin: 0 0 14px; font-size: 15px; letter-spacing: 0.5px; color: var(--blue); }
        .pf-skill-item { display: flex; align-items: center; gap: 10px; font-size: 13.5px; color: var(--text); padding: 6px 0; }
        .pf-skill-item::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: linear-gradient(135deg, var(--violet), var(--pink)); flex-shrink: 0; }

        .pf-timeline { border-left: 2px solid var(--card-border); padding-left: 30px; margin-left: 6px; }
        .pf-timeline-item { position: relative; margin-bottom: 34px; }
        .pf-timeline-item::before { content: ''; position: absolute; left: -37px; top: 4px; width: 14px; height: 14px; border-radius: 50%; background: linear-gradient(135deg, var(--violet), var(--blue)); box-shadow: 0 0 14px rgba(127,90,240,0.6); }
        .pf-timeline-role { font-size: 18px; font-weight: 700; margin-bottom: 2px; }
        .pf-timeline-org { color: var(--blue); font-size: 13.5px; margin-bottom: 4px; }
        .pf-timeline-period { color: var(--muted); font-size: 12px; margin-bottom: 12px; }
        .pf-timeline-item ul { margin: 0; padding-left: 18px; color: var(--muted); font-size: 14px; line-height: 1.8; }

        .pf-project-card { background: var(--card); border: 1px solid var(--card-border); border-radius: 20px; padding: 30px; backdrop-filter: blur(12px); transition: transform 0.25s ease, border-color 0.25s ease; }
        .pf-project-card:hover { transform: translateY(-6px); border-color: var(--pink); }
        .pf-project-card h3 { font-size: 20px; margin: 0 0 10px; }
        .pf-project-card p { color: var(--muted); font-size: 14px; line-height: 1.7; margin-bottom: 18px; }
        .pf-tags { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 18px; }
        .pf-tag { font-size: 11px; padding: 5px 11px; border-radius: 999px; background: rgba(127,90,240,0.12); border: 1px solid rgba(127,90,240,0.3); color: var(--text); }
        .pf-project-link { font-size: 13px; font-weight: 600; color: var(--blue); text-decoration: none; }

        .pf-cert-row { display: flex; align-items: center; gap: 16px; background: var(--card); border: 1px solid var(--card-border); border-radius: 16px; padding: 20px 26px; backdrop-filter: blur(12px); }
        .pf-cert-icon { width: 44px; height: 44px; border-radius: 12px; background: linear-gradient(135deg, var(--violet), var(--pink)); display: flex; align-items: center; justify-content: center; font-size: 20px; flex-shrink: 0; }

        .pf-contact-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; }
        .pf-form { display: flex; flex-direction: column; gap: 14px; }
        .pf-input, .pf-textarea { background: var(--card); border: 1px solid var(--card-border); border-radius: 12px; padding: 14px 16px; color: var(--text); font-family: inherit; font-size: 14px; outline: none; transition: border-color 0.2s ease; }
        .pf-input:focus, .pf-textarea:focus { border-color: var(--violet); }
        .pf-textarea { resize: vertical; min-height: 110px; }
        .pf-contact-info { display: flex; flex-direction: column; gap: 20px; justify-content: center; }
        .pf-contact-row { display: flex; align-items: center; gap: 14px; font-size: 14px; color: var(--muted); }
        .pf-contact-icon { width: 38px; height: 38px; border-radius: 10px; background: var(--card); border: 1px solid var(--card-border); display: flex; align-items: center; justify-content: center; }

        footer { position: relative; z-index: 2; padding: 40px 48px; border-top: 1px solid var(--card-border); display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }
        .pf-footer-links { display: flex; gap: 18px; }
        .pf-footer-links a { color: var(--muted); text-decoration: none; font-size: 18px; }

        @media (max-width: 900px) {
          .pf-nav { padding: 16px 20px; } .pf-navlinks { display: none; }
          .pf-hamburger { display: flex; }
          section { padding: 60px 22px; }
          .pf-hero { grid-template-columns: 1fr; min-height: auto; padding-top: 20px; gap: 40px; }
          .pf-hero-visual { height: 300px; order: -1; }
          .pf-photo-card { width: 160px; height: 160px; }
          .pf-chip { font-size: 10.5px; padding: 7px 11px; }
          .pf-contact-grid { grid-template-columns: 1fr; }
          .pf-stats { flex-wrap: wrap; gap: 24px; }
          .pf-grid-cards { grid-template-columns: 1fr; }
          .pf-modal-card { padding: 26px; }
          footer { flex-direction: column; text-align: center; }
        }
        @media (max-width: 480px) {
          .pf-headline { font-size: 32px; }
          .pf-cta-row { flex-direction: column; align-items: stretch; }
          .pf-cta-row button, .pf-cta-row a { text-align: center; }
        }
      `}</style>

      <div className={`pf-loader ${loaded ? "hidden" : ""}`}>
        <div className="pf-loader-ring" />
        <div className="pf-loader-text">Loading Portfolio</div>
      </div>

      <div className="pf-blob pf-blob-1" />
      <div className="pf-blob pf-blob-2" />
      <div className="pf-blob pf-blob-3" />

      <nav className="pf-nav">
        <div className="pf-logo">
          <svg className="pf-logo-mark" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
            <defs>
              <linearGradient id="pfLogoGrad" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0%" stopColor="#7F5AF0" />
                <stop offset="55%" stopColor="#2CB1FF" />
                <stop offset="100%" stopColor="#FF5DA2" />
              </linearGradient>
            </defs>
            <rect x="2" y="22" width="12" height="16" rx="4" fill="url(#pfLogoGrad)" opacity="0.55" />
            <rect x="14" y="12" width="12" height="26" rx="4" fill="url(#pfLogoGrad)" opacity="0.8" />
            <rect x="26" y="2" width="12" height="36" rx="4" fill="url(#pfLogoGrad)" />
          </svg>
        </div>
        <div className="pf-navlinks">
          <a href="#home" className={activeSection === "home" ? "active" : ""} onClick={(e) => { e.preventDefault(); document.getElementById("home")?.scrollIntoView({ behavior: "smooth" }); }}>Home</a>
          <a href="#about" className={activeSection === "about" ? "active" : ""} onClick={(e) => { e.preventDefault(); openModal("about"); }}>About</a>
          <a href="#skills" className={activeSection === "skills" ? "active" : ""} onClick={(e) => { e.preventDefault(); openModal("skills"); }}>Skills</a>
          <a href="#experience" className={activeSection === "experience" ? "active" : ""} onClick={(e) => { e.preventDefault(); openModal("experience"); }}>Experience</a>
          <a href="#projects" className={activeSection === "projects" ? "active" : ""} onClick={(e) => { e.preventDefault(); openModal("projects"); }}>Projects</a>
          <a href="#contact" className={activeSection === "contact" ? "active" : ""} onClick={(e) => { e.preventDefault(); openModal("contact"); }}>Contact</a>
        </div>
        <div className="pf-nav-right">
          <button className="pf-toggle" onClick={() => setTheme(isDark ? "light" : "dark")}>{isDark ? "☀" : "☾"}</button>
          <a className="pf-cta" style={{ textDecoration: "none", display: "inline-block" }} href={`${API_BASE}/api/public/resume`} download>Resume</a>
          <button className="pf-hamburger" onClick={() => setMobileOpen(true)}><span /><span /><span /></button>
        </div>
      </nav>

      {mobileOpen && <div className="pf-mobile-backdrop" onClick={() => setMobileOpen(false)} />}
      <div className={`pf-mobile-drawer ${mobileOpen ? "open" : ""}`}>
        <a onClick={() => { setMobileOpen(false); document.getElementById("home")?.scrollIntoView({ behavior: "smooth" }); }}>Home</a>
        <a onClick={() => openModal("about")}>About</a>
        <a onClick={() => openModal("skills")}>Skills</a>
        <a onClick={() => openModal("experience")}>Experience</a>
        <a onClick={() => openModal("projects")}>Projects</a>
        <a onClick={() => openModal("contact")}>Contact</a>
      </div>

      {modalKey && modalContent[modalKey] && (
        <div className="pf-modal-overlay" onClick={() => setModalKey(null)}>
          <div className="pf-modal-card" onClick={(e) => e.stopPropagation()}>
            <button className="pf-modal-close" onClick={() => setModalKey(null)}>✕</button>
            <div className="pf-modal-icon">{modalContent[modalKey].icon}</div>
            <h3>{modalContent[modalKey].title}</h3>
            <p>{modalContent[modalKey].teaser}</p>
            <button className="pf-cta" onClick={() => goToSection(modalKey)}>{modalContent[modalKey].cta} →</button>
          </div>
        </div>
      )}


      <section className="pf-hero" id="home">
        <div className="pf-reveal" style={{ animationDelay: "0.1s" }}>
          <div className="pf-eyebrow">● {profile.heroEyebrow || "Available for opportunities"}</div>
          <h1 className="pf-headline">
            {(profile.heroHeadline || "I build full-stack\nproducts that just work.").split("\n").map((line, i, arr) => (
              <React.Fragment key={i}>
                <span className={i === arr.length - 1 ? "pf-gradient-text" : ""}>{line}</span>
                {i < arr.length - 1 && <br />}
              </React.Fragment>
            ))}
          </h1>
          <p className="pf-sub">
            {profile.heroSub || "Java Full Stack Developer crafting scalable Spring Boot backends and smooth React interfaces, backed by production-style projects with auth, RBAC, and cloud integrations."}
          </p>
          <div className="pf-cta-row">
            <button className="pf-cta" onClick={() => document.getElementById('projects')?.scrollIntoView({behavior:'smooth'})}>View Projects</button>
            <a className="pf-btn-ghost" style={{ textDecoration: "none" }} href={`${API_BASE}/api/public/resume`} download>Download Résumé</a>
          </div>
          <div className="pf-stats">
            <div><div className="pf-stat-num">{projects.length}+</div><div className="pf-stat-label">Full-stack projects</div></div>
            <div><div className="pf-stat-num">{profile.statExperience || "6mo"}</div><div className="pf-stat-label">Experience</div></div>
            <div><div className="pf-stat-num">{profile.statCgpa || "8.47"}</div><div className="pf-stat-label">CGPA</div></div>
          </div>
        </div>
        <div className="pf-hero-visual pf-reveal" style={{ animationDelay: "0.3s" }}>
          <div className="pf-canvas-wrap" ref={mountRef} />
          <div className="pf-photo-card">
            <img
              src={profile.photoAvailable ? `${API_BASE}/api/public/photo` : `data:image/jpeg;base64,${PHOTO_B64}`}
              onError={(e) => { e.target.onerror = null; e.target.src = `data:image/jpeg;base64,${PHOTO_B64}`; }}
              alt={profile.fullName || "Profile"}
            />
          </div>
          <div className="pf-chip pf-chip-1"><span className="pf-chip-dot" />Spring Boot — online</div>
          <div className="pf-chip pf-chip-2"><span className="pf-chip-dot" />React.js build passed</div>
        </div>
      </section>

      <section id="about">
        <div className="pf-eyebrow">Who I Am</div>
        <h2 className="pf-h2">About <span className="pf-gradient-text">Me</span></h2>
        <p className="pf-section-sub">
          {profile.bio || "Computer Engineering graduate with hands-on experience in Java Full Stack Development. I build full-stack applications with JWT Authentication, Role-Based Access Control, and real database integration — from REST APIs down to the UI that consumes them."}
        </p>
        <div className="pf-grid-cards">
          <div className="pf-card pf-observe">
            <h3>🎓 EDUCATION</h3>
            <div className="pf-skill-item">B.E. Computer Engineering</div>
            <div className="pf-skill-item">Kaviyatri Bahinabai Chaudhari North Maharashtra University</div>
            <div className="pf-skill-item">2020 – 2024 · CGPA 8.47</div>
          </div>
          <div className="pf-card pf-observe">
            <h3>💼 FOCUS</h3>
            <div className="pf-skill-item">Backend architecture with Spring Boot</div>
            <div className="pf-skill-item">Responsive React interfaces</div>
            <div className="pf-skill-item">Secure auth (JWT + RBAC)</div>
          </div>
          <div className="pf-card pf-observe">
            <h3>🎯 SEEKING</h3>
            <div className="pf-skill-item">Software Developer role</div>
            <div className="pf-skill-item">Java Full Stack Developer role</div>
          </div>
        </div>
      </section>

      <section id="skills">
        <div className="pf-eyebrow">What I Work With</div>
        <h2 className="pf-h2">Technical <span className="pf-gradient-text">Skills</span></h2>
        <p className="pf-section-sub">Tools and technologies I use to ship full-stack applications end to end.</p>
        <div className="pf-grid-cards">
          {skills.map((s) => (
            <div className="pf-card pf-observe" key={s.cat}>
              <h3>{s.cat.toUpperCase()}</h3>
              {s.items.map((it) => <div className="pf-skill-item" key={it}>{it}</div>)}
            </div>
          ))}
        </div>
      </section>

      <section id="experience">
        <div className="pf-eyebrow">Where I've Worked</div>
        <h2 className="pf-h2">Experience</h2>
        <p className="pf-section-sub">Real-world experience building and shipping features across the stack.</p>
        <div className="pf-timeline">
          {experience.map((e) => (
            <div className="pf-timeline-item pf-observe" key={e.role}>
              <div className="pf-timeline-role">{e.role}</div>
              <div className="pf-timeline-org">{e.org}</div>
              <div className="pf-timeline-period">{e.period}</div>
              <ul>{e.points.map((p) => <li key={p}>{p}</li>)}</ul>
            </div>
          ))}
        </div>
      </section>

      <section id="projects">
        <div className="pf-eyebrow">What I've Built</div>
        <h2 className="pf-h2">Featured <span className="pf-gradient-text">Projects</span></h2>
        <p className="pf-section-sub">A couple of full-stack builds that show how I put the pieces together.</p>
        <div className="pf-grid-cards">
          {projects.map((p) => (
            <div className="pf-project-card pf-observe" key={p.title}>
              <h3>{p.title}</h3>
              <p>{p.desc}</p>
              <div className="pf-tags">{p.tags.map((t) => <span className="pf-tag" key={t}>{t}</span>)}</div>
              <a className="pf-project-link" href={p.link} target="_blank" rel="noreferrer">View on GitHub →</a>
            </div>
          ))}
        </div>
      </section>

      <section id="certifications">
        <div className="pf-eyebrow">Verified</div>
        <h2 className="pf-h2">Certifications</h2>
        {certifications.map((c, i) => (
          <div className="pf-cert-row pf-observe" key={i} style={{ marginBottom: 12 }}>
            <div className="pf-cert-icon">🏆</div>
            <div>
              <div style={{ fontWeight: 600 }}>{c.title}</div>
              <div style={{ color: "var(--muted)", fontSize: 13 }}>{c.issuer}{c.year ? ` · ${c.year}` : ""}</div>
            </div>
          </div>
        ))}
      </section>

      <section id="contact">
        <div className="pf-eyebrow">Get In Touch</div>
        <h2 className="pf-h2">Let's Build <span className="pf-gradient-text">Something</span></h2>
        <p className="pf-section-sub">Open to Software Developer / Java Full Stack roles — reach out anytime.</p>
        <div className="pf-contact-grid">
          <form className="pf-form" onSubmit={submitContact}>
            <input className="pf-input" placeholder="Your Name" required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
            <input className="pf-input" placeholder="Your Email" required type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
            <textarea className="pf-textarea" placeholder="Your Message" required value={form.message} onChange={(e) => setForm({ ...form, message: e.target.value })} />
            <button className="pf-cta" style={{ alignSelf: "flex-start" }}>Send Message</button>
            {formStatus && <div style={{ color: "var(--muted)", fontSize: 13 }}>{formStatus}</div>}
          </form>
          <div className="pf-contact-info">
            <a className="pf-contact-row" style={{ textDecoration: "none" }} href={`mailto:${profile.email || "pushpakchopadekar@gmail.com"}`}><span className="pf-contact-icon">📧</span> {profile.email || "pushpakchopadekar@gmail.com"}</a>
            <a className="pf-contact-row" style={{ textDecoration: "none" }} href={`tel:${(profile.phone || "+91 7387416715").replace(/\s/g, "")}`}><span className="pf-contact-icon">📱</span> {profile.phone || "+91 7387416715"}</a>
            {profile.githubUrl && <a className="pf-contact-row" style={{ textDecoration: "none" }} href={profile.githubUrl} target="_blank" rel="noreferrer"><span className="pf-contact-icon">💻</span> GitHub</a>}
            {profile.linkedinUrl && <a className="pf-contact-row" style={{ textDecoration: "none" }} href={profile.linkedinUrl} target="_blank" rel="noreferrer"><span className="pf-contact-icon">🔗</span> LinkedIn</a>}
          </div>
        </div>
      </section>

      <footer>
        <div className="pf-logo">
          <svg className="pf-logo-mark" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
            <rect x="2" y="22" width="12" height="16" rx="4" fill="url(#pfLogoGrad)" opacity="0.55" />
            <rect x="14" y="12" width="12" height="26" rx="4" fill="url(#pfLogoGrad)" opacity="0.8" />
            <rect x="26" y="2" width="12" height="36" rx="4" fill="url(#pfLogoGrad)" />
          </svg>
        </div>
        <div style={{ color: "var(--muted)", fontSize: 13 }}>© 2026 Pushpak Chopadekar. All rights reserved.</div>
        <div className="pf-footer-links">
          {profile.githubUrl && <a href={profile.githubUrl} target="_blank" rel="noreferrer">GH</a>}
          {profile.linkedinUrl && <a href={profile.linkedinUrl} target="_blank" rel="noreferrer">LI</a>}
          <a href={`mailto:${profile.email || "pushpakchopadekar@gmail.com"}`}>✉</a>
        </div>
      </footer>
    </div>
  );
}
